double wheel_cmd[3] = {0.0, 0.0, 0.0};
double wheel_limit[3];
double wheel_slew[3];
unint32 avail, sat_mask = 0U, slew_mask = 0U, unavail_mask = 0U;
int valid = 1;
int any_limit = 0;
int any_missing = 0;
adcs_vec3_t achieved = {0.0, 0.0, 0.0};
adcs_vec3_t residual;
double residual_norm;
wa_mode_t mode;

/* Disable: reset NORMAL and previous commands to zero. */
if (!en) {
    wa_state.mode = WA_NORMAL;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
    wa_state.previous_wheel_torque_nm[0] = 0.0;
    wa_state.previous_wheel_torque_nm[1] = 0.0;
    wa_state.previous_wheel_torque_nm[2] = 0.0;
    wa_output.mode = WA_NORMAL;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_norm_nm = 0.0;
    return;
}

/* Latch FAULT until disable. */
if (wa_state.mode == WA_FAULT) {
    wa_output.mode = WA_FAULT;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_norm_nm = 0.0;
    return;
}

/* Validate inputs and configuration. */
if (wa_input.requested_torque_nm == NULL) valid = 0;
else if (!adcs_is_finite_vec3(wa_input.requested_torque_nm)) valid = 0;
if (valid && wa_input.axes == NULL) valid = 0;
if (valid && wa_input.axis_count != 3U) valid = 0;
if (valid && (wa_input.available_mask & ~0x7U) != 0U) valid = 0;
if (valid) {
    unint32 m = wa_input.available_mask & 0x7U;
    unint32 cnt = 0U;
    for (i = 0; i < 3U; i++) if (m & (1U << i)) cnt++;
    if (cnt < 2U) valid = 0;
}
for (i = 0; valid && (i < 3U); i++) {
    if ((!isfinite(wa_config.wheel_limit_nm[i])) ||
        (wa_config.wheel_limit_nm[i] <= 0.0)) valid = 0;
    if ((!isfinite(wa_config.max_wheel_slew_nm_per_cycle[i])) ||
        (wa_config.max_wheel_slew_nm_per_cycle[i] <= 0.0)) valid = 0;
}
if (valid && ((wa_config.release_cycles < 1U) || (wa_config.release_cycles > 20U))) valid = 0;
if (valid && ((wa_config.restore_cycles < 1U) || (wa_config.restore_cycles > 20U))) valid = 0;

if (valid) {
    for (i = 0; i < 3U; i++) {
        if (!adcs_is_finite_vec3(&wa_input.axes[i])) { valid = 0; break; }
        if (adcs_vec3_normalize(&wa_input.axes[i], ADCS_EPS_NORM, &axes[i]) != ADCS_OK) {
            valid = 0; break;
        }
    }
}
if (valid) {
    double d01 = fabs(adcs_vec3_dot(&axes[0], &axes[1]));
    double d02 = fabs(adcs_vec3_dot(&axes[0], &axes[2]));
    double d12 = fabs(adcs_vec3_dot(&axes[1], &axes[2]));
    if ((d01 > ADCS_EPS_COLLINEAR) || (d02 > ADCS_EPS_COLLINEAR) ||
        (d12 > ADCS_EPS_COLLINEAR)) valid = 0;
}

if (!valid) {
    wa_state.mode = WA_FAULT;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
    wa_state.previous_wheel_torque_nm[0] = 0.0;
    wa_state.previous_wheel_torque_nm[1] = 0.0;
    wa_state.previous_wheel_torque_nm[2] = 0.0;
    wa_output.mode = WA_FAULT;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_norm_nm = 0.0;
    return;
}

req = *wa_input.requested_torque_nm;
avail = wa_input.available_mask & 0x7U;
for (i = 0; i < 3U; i++) {
    wheel_limit[i] = wa_config.wheel_limit_nm[i];
    wheel_slew[i] = wa_config.max_wheel_slew_nm_per_cycle[i];
}

for (i = 0; i < 3U; i++) {
    if ((avail & (1U << i)) == 0U) {
        wheel_cmd[i] = 0.0;
        unavail_mask |= (1U << i);
        any_missing = 1;
        continue;
    }
    wheel_cmd[i] = -adcs_vec3_dot(&axes[i], &req);
    if (wheel_cmd[i] > wheel_limit[i]) {
        wheel_cmd[i] = wheel_limit[i];
        sat_mask |= (1U << i);
        any_limit = 1;
    } else if (wheel_cmd[i] < -wheel_limit[i]) {
        wheel_cmd[i] = -wheel_limit[i];
        sat_mask |= (1U << i);
        any_limit = 1;
    }
    {
        double prev = wa_state.previous_wheel_torque_nm[i];
        double delta = wheel_cmd[i] - prev;
        if (delta > wheel_slew[i]) {
            wheel_cmd[i] = prev + wheel_slew[i];
            slew_mask |= (1U << i);
            any_limit = 1;
        } else if (delta < -wheel_slew[i]) {
            wheel_cmd[i] = prev - wheel_slew[i];
            slew_mask |= (1U << i);
            any_limit = 1;
        }
    }
}

for (i = 0; i < 3U; i++) {
    adcs_vec3_t term = adcs_vec3_scale(&axes[i], wheel_cmd[i]);
    achieved = adcs_vec3_add(&achieved, &term);
}
residual = adcs_vec3_sub(&req, &achieved);
residual_norm = adcs_vec3_norm(&residual);

/* Mode transitions: limit events take precedence over health recovery. */
if (any_limit) {
    mode = WA_LIMITED;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
} else if (any_missing) {
    mode = WA_DEGRADED;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
} else {
    if (wa_state.mode == WA_LIMITED || wa_state.mode == WA_DEGRADED) {
        wa_state.clean_count++;
        if (wa_state.clean_count >= wa_config.release_cycles) {
            wa_state.clean_count = 0U;
            wa_state.restore_count = 0U;
            mode = WA_RECOVERING;
        } else {
            mode = wa_state.mode;
        }
    } else if (wa_state.mode == WA_RECOVERING) {
        wa_state.restore_count++;
        if (wa_state.restore_count >= wa_config.restore_cycles) {
            wa_state.restore_count = 0U;
            wa_state.clean_count = 0U;
            mode = WA_NORMAL;
        } else {
            mode = WA_RECOVERING;
        }
    } else {
        mode = WA_NORMAL;
    }
}
wa_state.mode = mode;

wa_state.previous_wheel_torque_nm[0] = wheel_cmd[0];
wa_state.previous_wheel_torque_nm[1] = wheel_cmd[1];
wa_state.previous_wheel_torque_nm[2] = wheel_cmd[2];

wa_output.mode = mode;
wa_output.clean_count = wa_state.clean_count;
wa_output.restore_count = wa_state.restore_count;
wa_output.saturation_mask = sat_mask;
wa_output.slew_mask = slew_mask;
wa_output.unavailable_mask = unavail_mask;
wa_output.wheel_torque_nm[0] = wheel_cmd[0];
wa_output.wheel_torque_nm[1] = wheel_cmd[1];
wa_output.wheel_torque_nm[2] = wheel_cmd[2];
wa_output.achieved_torque_nm = achieved;
wa_output.residual_torque_nm = residual;
wa_output.residual_norm_nm = residual_norm;

