if (wa_input.axis_count != 3u)
    valid = 0;
if (wa_input.requested_torque_nm == NULL)
    valid = 0;
if (wa_input.axes == NULL)
    valid = 0;
if ((wa_input.available_mask & 0xFFFFFFF8u) != 0u)
    valid = 0;
if (!adcs_is_finite_vec3(wa_input.requested_torque_nm))
    valid = 0;
if ((wa_input.available_mask & 0x07u) == 0u)
    valid = 0;
if (wa_config.release_cycles < 1u || wa_config.release_cycles > 20u)
    valid = 0;
if (wa_config.restore_cycles < 1u || wa_config.restore_cycles > 20u)
    valid = 0;
for (i = 0u; i < 3u; i++) {
    if (!isfinite(wa_config.wheel_limit_nm[i]) || wa_config.wheel_limit_nm[i] <= 0.0)
        valid = 0;
    if (!isfinite(wa_config.max_wheel_slew_nm_per_cycle[i]) ||
        wa_config.max_wheel_slew_nm_per_cycle[i] <= 0.0)
        valid = 0;
    if (!adcs_is_finite_vec3(&wa_input.axes[i]))
        valid = 0;
}
if (valid) {
    for (i = 0u; i < 3u; i++) {
        if (adcs_vec3_normalize(&wa_input.axes[i], ADCS_EPS_NORM, &axes_n[i]) != ADCS_OK) {
            valid = 0;
            break;
        }
    }
