if (valid) {
    for (i = 0u; i < 3u && valid; i++) {
        for (j = i + 1u; j < 3u && valid; j++) {
            double d = adcs_vec3_dot(&axes_n[i], &axes_n[j]);
            if (fabs(d) > ADCS_EPS_COLLINEAR)
