}

/* Allocate per available wheel: -axis dot requested, magnitude limit, slew limit. */
for (i = 0u; i < 3u; i++) {
    if ((wa_input.available_mask & (1u << i)) == 0u) {
        wheel_cmd[i] = 0.0;
        continue;
    }
    {
        double u = -adcs_vec3_dot(&axes_n[i], &req);
        double limit = wa_config.wheel_limit_nm[i];
        if (u > limit) {
            u = limit;
            local_sat |= (1u << i);
