        {
            double delta = u - wa_state.previous_wheel_torque_nm[i];
            double slew = wa_config.max_wheel_slew_nm_per_cycle[i];
            if (delta > slew) {
                u = wa_state.previous_wheel_torque_nm[i] + slew;
                local_slew |= (1u << i);
            } else if (delta < -slew) {
                u = wa_state.previous_wheel_torque_nm[i] - slew;
                local_slew |= (1u << i);
