size_t i, j;
int fault = 0;
int available_count = 0;
int missing = 0;
int any_limit = 0;
int all_healthy_unsaturated = 1;
adcs_vec3_t axes_n[3];
double dotv;
double raw[3];
double mag[3];
double commanded[3];
double torque_nm[3];
adcs_vec3_t achieved = {0.0, 0.0, 0.0};
adcs_vec3_t term;

wa_state.mode = wa_state.mode;

/* 合法性门槛：无效标志/掩码/配置/轴、null 或非有限 requested 锁 FAULT */
if ((wa_input.requested_torque_nm == NULL) || (wa_input.axes == NULL)) {
    fault = 1;
} else if (wa_input.axis_count != 3U) {
    fault = 1;
} else if ((wa_input.available_mask & ~0x7U) != 0U) {
    fault = 1;
} else if (!adcs_is_finite_vec3(wa_input.requested_torque_nm)) {
    fault = 1;
} else {
    for (i = 0; i < 3U; i++) {
        if (!adcs_is_finite_vec3(&wa_input.axes[i])) {
            fault = 1;
            break;
        }
        if (adcs_vec3_normalize(&wa_input.axes[i], ADCS_EPS_NORM, &axes_n[i]) != ADCS_OK) {
            fault = 1;
            break;
        }
    }
}
if (!fault) {
    for (i = 0; i < 3U && !fault; i++) {
        for (j = i + 1U; j < 3U; j++) {
            dotv = adcs_vec3_dot(&axes_n[i], &axes_n[j]);
            if (fabs(dotv) > ADCS_EPS_COLLINEAR) {
                fault = 1;
                break;
            }
        }
    }
}
if (!fault) {
    for (i = 0; i < 3U; i++) {
        if ((!isfinite(wa_config.wheel_limit_nm[i])) || (wa_config.wheel_limit_nm[i] <= 0.0)) {
            fault = 1;
            break;
        }
        if ((!isfinite(wa_config.max_wheel_slew_nm_per_cycle[i])) ||
            (wa_config.max_wheel_slew_nm_per_cycle[i] <= 0.0)) {
            fault = 1;
            break;
        }
        if (!isfinite(wa_state.previous_wheel_torque_nm[i])) {
            fault = 1;
            break;
        }
    }
}
if (!fault) {
    if ((wa_config.release_cycles < 1U) || (wa_config.release_cycles > 20U)) fault = 1;
    else if ((wa_config.restore_cycles < 1U) || (wa_config.restore_cycles > 20U)) fault = 1;
}

if (fault) {
    wa_state.mode = WA_FAULT;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
    for (i = 0; i < 3U; i++) {
        wa_state.previous_wheel_torque_nm[i] = 0.0;
        wa_output.wheel_torque_nm[i] = 0.0;
    }
    wa_output.mode = WA_FAULT;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0x7U;
    wa_output.achieved_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_norm_nm = 0.0;
    return;
}

/* Disable：重置 NORMAL 与前一命令为零 */
if (!wa_input.enable) {
    wa_state.mode = WA_NORMAL;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
    for (i = 0; i < 3U; i++) {
        wa_state.previous_wheel_torque_nm[i] = 0.0;
        wa_output.wheel_torque_nm[i] = 0.0;
    }
    wa_output.mode = WA_NORMAL;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = (~wa_input.available_mask) & 0x7U;
    wa_output.achieved_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    wa_output.residual_torque_nm = *wa_input.requested_torque_nm;
    wa_output.residual_norm_nm = adcs_vec3_norm(wa_input.requested_torque_nm);
    return;
}

/* 可用轮计数：逐 bit 扫描，至少2个 */
available_count = 0;
for (i = 0; i < 3U; i++) {
    if ((wa_input.available_mask & (1U << i)) != 0U) available_count++;
}
missing = (available_count < 2) ? 1 : 0;

wa_output.saturation_mask = 0U;
wa_output.slew_mask = 0U;
wa_output.unavailable_mask = (~wa_input.available_mask) & 0x7U;

/* 逐轮分配 */
for (i = 0; i < 3U; i++) {
    if ((wa_input.available_mask & (1U << i)) == 0U) {
        commanded[i] = 0.0;
        torque_nm[i] = 0.0;
        continue;
    }
    raw[i] = -adcs_vec3_dot(&axes_n[i], wa_input.requested_torque_nm);
    if (raw[i] > wa_config.wheel_limit_nm[i]) {
        mag[i] = wa_config.wheel_limit_nm[i];
        wa_output.saturation_mask |= (unint32)(1U << i);
    } else if (raw[i] < -wa_config.wheel_limit_nm[i]) {
        mag[i] = -wa_config.wheel_limit_nm[i];
        wa_output.saturation_mask |= (unint32)(1U << i);
    } else {
        mag[i] = raw[i];
    }
    {
        double delta = mag[i] - wa_state.previous_wheel_torque_nm[i];
        if (delta > wa_config.max_wheel_slew_nm_per_cycle[i]) {
            commanded[i] = wa_state.previous_wheel_torque_nm[i] +
                           wa_config.max_wheel_slew_nm_per_cycle[i];
            wa_output.slew_mask |= (unint32)(1U << i);
        } else if (delta < -wa_config.max_wheel_slew_nm_per_cycle[i]) {
            commanded[i] = wa_state.previous_wheel_torque_nm[i] -
                           wa_config.max_wheel_slew_nm_per_cycle[i];
            wa_output.slew_mask |= (unint32)(1U << i);
        } else {
            commanded[i] = mag[i];
        }
    }
    torque_nm[i] = commanded[i];
}

/* 重建 achieved 与 residual */
for (i = 0; i < 3U; i++) {
    term = adcs_vec3_scale(&axes_n[i], torque_nm[i]);
    achieved = adcs_vec3_add(&achieved, &term);
}
wa_output.achieved_torque_nm = achieved;
wa_output.residual_torque_nm = adcs_vec3_sub(wa_input.requested_torque_nm, &achieved);
wa_output.residual_norm_nm = adcs_vec3_norm(&wa_output.residual_torque_nm);

for (i = 0; i < 3U; i++) {
    wa_output.wheel_torque_nm[i] = torque_nm[i];
    wa_state.previous_wheel_torque_nm[i] = torque_nm[i];
}

/* 判断本次是否有轮不健康/饱和/速率受限 */
any_limit = (wa_output.saturation_mask != 0U) || (wa_output.slew_mask != 0U) ? 1 : 0;
for (i = 0; i < 3U; i++) {
    if ((wa_input.available_mask & (1U << i)) == 0U) all_healthy_unsaturated = 0;
}
if (any_limit) all_healthy_unsaturated = 0;

/* 状态机 */
if (missing) {
    wa_state.mode = WA_DEGRADED;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
} else if (wa_state.mode == WA_FAULT) {
    wa_state.mode = WA_DEGRADED;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
} else if (any_limit) {
    wa_state.mode = WA_LIMITED;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
} else if (wa_state.mode == WA_LIMITED) {
    wa_state.clean_count++;
    if (wa_state.clean_count >= wa_config.release_cycles) {
        wa_state.clean_count = 0U;
        wa_state.mode = WA_NORMAL;
    }
} else if (wa_state.mode == WA_DEGRADED) {
    if (all_healthy_unsaturated) {
        wa_state.mode = WA_RECOVERING;
        wa_state.restore_count = 1U;
        wa_state.clean_count = 0U;
    } else {
        wa_state.restore_count = 0U;
    }
} else if (wa_state.mode == WA_RECOVERING) {
    if (!all_healthy_unsaturated) {
        wa_state.mode = WA_DEGRADED;
        wa_state.restore_count = 0U;
    } else {
        wa_state.restore_count++;
        if (wa_state.restore_count >= wa_config.restore_cycles) {
            wa_state.restore_count = 0U;
            wa_state.mode = WA_NORMAL;
        }
    }
} else {
    wa_state.mode = WA_NORMAL;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
}

wa_output.mode = wa_state.mode;
wa_output.clean_count = wa_state.clean_count;
wa_output.restore_count = wa_state.restore_count;

return;

